// Tudo chega como texto (o app manda formulário simples).
const corpo = $('Recebe pedido do app').first().json.body || {};
const texto = (v) => String(v ?? '').trim();
const ACOES = ['salvar', 'resumo', 'cliente', 'substituir', 'desfazer', 'editar'];
const acao = ACOES.includes(texto(corpo.acao)) ? texto(corpo.acao) : '';
let erro = acao ? '' : 'Ação inválida.';

// Por enquanto só os PDFs gerados no app; "servico" e "relatorio_tecnico" entram quando forem definidos.
const TIPOS = ['nfs', 'orcamento', 'recibo', 'comunicado', 'laudo'];
const ORIGENS = ['gerado', 'importado'];
const origem = texto(corpo.origem) || 'gerado';
const clienteId = texto(corpo.clienteId);
const tipo = texto(corpo.tipo);
const titulo = texto(corpo.titulo).replace(/\s+/g, ' ').slice(0, 200);
const descricao = texto(corpo.descricao).replace(/\s+/g, ' ').slice(0, 500);
const textoBusca = texto(corpo.textoBusca).slice(0, 20000);
const clienteNome = texto(corpo.clienteNome).replace(/\s+/g, ' ').slice(0, 200);
const dataDocumento = texto(corpo.dataDocumento);
const emissor = texto(corpo.emissor) === 'CNPJ 2' ? 'CNPJ 2' : 'CNPJ 1';
const hash = texto(corpo.hash).toLowerCase();
const dadosJson = texto(corpo.dadosJson).slice(0, 100000);

// Valor em reais: vazio = sem valor (comunicado e laudo não têm). Aceita 290 / 290,5 / 1.290,50 / 290.50.
let bruto = texto(corpo.valor).replace(/\s+/g, '').replace(/^R\$/i, '');
if (bruto.includes(',')) bruto = bruto.replace(/\./g, '').replace(',', '.');
let valor = null;
if (bruto) {
  if (/^\d{1,9}(\.\d{1,2})?$/.test(bruto)) valor = Number(bruto);
  else if (!erro) erro = 'Valor inválido.';
}

// PDF em base64, até uns 8 MB.
let arquivo = texto(corpo.arquivo).replace(/^data:[^,]*,/, '');
let nomeArquivo = texto(corpo.nomeArquivo).replace(/[\\/:*?"<>|\x00-\x1f]/g, '_').slice(0, 150) || 'documento.pdf';
if (!/\.pdf$/i.test(nomeArquivo)) nomeArquivo += '.pdf';

if (!erro && !/^rec[A-Za-z0-9]{14}$/.test(clienteId) && acao !== 'resumo') erro = 'Escolha um cliente do cadastro.';
if (!erro && acao === 'salvar') {
  if (!TIPOS.includes(tipo)) erro = 'Tipo de documento inválido.';
  else if (!ORIGENS.includes(origem)) erro = 'Origem inválida.';
  else if (!titulo) erro = 'Falta o título do documento.';
  else if (!/^\d{4}-\d{2}-\d{2}$/.test(dataDocumento)) erro = 'Data do documento inválida.';
  else if (hash && !/^[0-9a-f]{64}$/.test(hash)) erro = 'Identificação do arquivo inválida.';
  else if (!arquivo || !/^[A-Za-z0-9+/=]+$/.test(arquivo)) erro = 'Arquivo inválido.';
  else if (!arquivo.startsWith('JVBERi0')) erro = 'O arquivo precisa ser um PDF.';
  else if (arquivo.length > 11 * 1024 * 1024) erro = 'O PDF passa de 8 MB.';
}
// Troca de documento (17/11/2026): "substituir" liga o antigo ao novo; "desfazer" tira a ligação.
const antigoId = texto(corpo.antigoId);
const novoId = texto(corpo.novoId);
const motivo = texto(corpo.motivo).replace(/\s+/g, ' ').slice(0, 200);
if (!erro && (acao === 'substituir' || acao === 'desfazer')) {
  if (!/^rec[A-Za-z0-9]{14}$/.test(antigoId) || !/^rec[A-Za-z0-9]{14}$/.test(novoId)) erro = 'Escolha os dois documentos.';
  else if (antigoId === novoId) erro = 'O documento novo precisa ser outro.';
}
// Corrigir os dados de um documento (22/11/2026): usa a mesma busca da troca (o mesmo documento nos dois lados).
const id = texto(corpo.id);
if (!erro && acao === 'editar') {
  if (!/^rec[A-Za-z0-9]{14}$/.test(id)) erro = 'Documento inválido.';
  else if (!titulo) erro = 'Falta o título do documento.';
  else if (!/^\d{4}-\d{2}-\d{2}$/.test(dataDocumento)) erro = 'Data do documento inválida.';
}
return [{ json: { acao, origem, clienteId, tipo, titulo, descricao, textoBusca, clienteNome, dataDocumento, valor, emissor, hash, dadosJson, arquivo, nomeArquivo, antigoId: acao === 'editar' ? id : antigoId, novoId: acao === 'editar' ? id : novoId, motivo, erro } }];

const e = $('Le entrada').first().json;
const cab = $('Recebe pedido do app').first().json.headers || {};
// Anexo guardado no PC vem com endereço relativo (/webhook/anexo...): completa com o endereço por onde o app
// chegou (o túnel), senão o PDF não abre no celular.
const origem = String(cab['x-forwarded-proto'] || 'http').split(',')[0].trim() + '://' + (cab['x-forwarded-host'] || cab.host || 'localhost:5678');
const urlAnexo = (u) => (String(u || '').startsWith('/') ? origem + u : u);
const lista = (no) => { try { return $(no).all().map((i) => i.json).filter((j) => j && j.id && j.fields); } catch (err) { return []; } };
const falhou = (no) => { try { return $(no).all().some((i) => i.json && i.json.error); } catch (err) { return false; } };
if (falhou('Busca arquivos') || falhou('Busca notas')) return [{ json: { ok: false, mensagem: 'Não foi possível falar com o banco agora. Tente de novo em instantes.' } }];

// NFS-e: em produção só aparecem as notas de verdade; no ambiente de testes, só as de teste (igual à página de notas).
let saude = {};
try { saude = $('Status do servico').first().json || {}; } catch (err) { saude = {}; }
const ambiente = saude.ok === true && saude.ambiente === 'restrita' ? 'Testes' : 'Producao';

// Troca de documento (17/11/2026): no Dados_Json, "substituidoPor" (no antigo) e "substitui" (no novo), cada um com
// { data: 'AAAA-MM-DD', titulo, motivo }. Só data, título e motivo curtos vão para o app.
const troca = (v) => (v && typeof v === 'object' && /^\d{4}-\d{2}-\d{2}$/.test(String(v.data || ''))
  ? { id: /^rec[A-Za-z0-9]{14}$/.test(String(v.id || '')) ? String(v.id) : '', data: String(v.data), titulo: String(v.titulo || '').slice(0, 200), motivo: String(v.motivo || '').slice(0, 200) } : null);
const arquivos = lista('Busca arquivos').map((r) => {
  const f = r.fields;
  let dados = {};
  try { dados = JSON.parse(f.Dados_Json || '{}') || {}; } catch (err) { dados = {}; }
  const anexo = (f.Arquivo || [])[0] || null;
  return { id: r.id, clienteId: f.Cliente_Ref || '', pasta: f.Tipo, titulo: f.Titulo || '', descricao: f.Descricao || '', data: f.Data_Documento || '',
    valor: typeof f.Valor === 'number' ? f.Valor : null, emissor: f.Emissor || 'CNPJ 1', origem: f.Origem || 'gerado',
    texto: e.acao === 'cliente' ? String(f.Texto_Busca || '').slice(0, 4000) : '',
    substituidoPor: troca(dados.substituidoPor), substitui: troca(dados.substitui),
    arquivo: anexo ? { nome: anexo.filename, url: urlAnexo(anexo.url), tamanho: anexo.size || 0 } : null };
});
// Nota cancelada (16/11/2026) continua na pasta, marcada como cancelada.
const notas = lista('Busca notas').filter((r) => (r.fields.Status === 'Emitida' || r.fields.Status === 'Cancelada') && r.fields.Ambiente === ambiente).map((r) => {
  const f = r.fields;
  return { id: r.id, clienteId: f.Cliente_Ref || '', pasta: 'nfs', titulo: f.Numero_NFSe ? 'Nota nº ' + f.Numero_NFSe : 'Nota (pedido nº ' + f.Numero_DPS + ')',
    descricao: f.Descricao || '', data: f.Competencia || '', valor: typeof f.Valor === 'number' ? f.Valor : null, emissor: f.Emissor || 'CNPJ 1',
    cancelada: f.Status === 'Cancelada',
    texto: e.acao === 'cliente' ? [f.Tomador_Nome, f.Obra, f.Descricao, f.Chave_Acesso].filter(Boolean).join(' | ').slice(0, 4000) : '',
    // O PDF da nota (16/11/2026) abre como os outros arquivos da pasta.
    arquivo: (f.Pdf_Nota || [])[0] ? { nome: f.Pdf_Nota[0].filename, url: urlAnexo(f.Pdf_Nota[0].url), tamanho: f.Pdf_Nota[0].size || 0 } : null,
    nota: { chave: f.Chave_Acesso || '', numero: f.Numero_NFSe || '', tomador: f.Tomador_Nome || '', documento: f.Tomador_Documento || '', obra: f.Obra || '', ambiente: f.Ambiente } };
});
const todos = arquivos.concat(notas);

if (e.acao === 'resumo') {
  const porCliente = {};
  for (const it of todos) {
    if (!it.clienteId) continue;
    const c = (porCliente[it.clienteId] = porCliente[it.clienteId] || { total: 0, pastas: {} });
    c.total++;
    c.pastas[it.pasta] = (c.pastas[it.pasta] || 0) + 1;
  }
  return [{ json: { ok: true, ambiente, clientes: porCliente } }];
}
const doCliente = todos.filter((it) => it.clienteId === e.clienteId).sort((a, b) => String(b.data).localeCompare(String(a.data)));
return [{ json: { ok: true, ambiente, itens: doCliente } }];

const e = $('Le entrada').first().json;
const achados = $('Busca duplicado').all().map((i) => i.json).filter((j) => j && j.id && j.fields);
// O mesmo PDF (mesma impressão digital) do mesmo cliente não é guardado duas vezes.
const dup = e.hash ? achados.find((r) => r.fields.Cliente_Ref === e.clienteId) : null;
if (dup) return [{ json: { proximo: 'responder', resposta: { ok: true, jaGuardado: true, id: dup.id, mensagem: 'Esta cópia já estava guardada na pasta do cliente.' } } }];
const fields = {
  Cliente_Ref: e.clienteId, Cliente_Nome: e.clienteNome, Tipo: e.tipo, Titulo: e.titulo, Descricao: e.descricao,
  Texto_Busca: e.textoBusca, Data_Documento: e.dataDocumento, Emissor: e.emissor, Origem: e.origem, Dados_Json: e.dadosJson,
};
if (e.valor !== null) fields.Valor = e.valor;
if (e.hash) fields.Hash_PDF = e.hash;
return [{ json: { proximo: 'gravar', url: 'http://127.0.0.1:5690/v0/app6PyYmtFduIMp7B/tblArquivosClie01', corpo: { fields } } }];

const e = $('Le entrada').first().json;
const id = $json.id || (($json.records || [])[0] || {}).id;
return [{ json: {
  url: 'http://127.0.0.1:5690/v0/app6PyYmtFduIMp7B/' + id + '/Arquivo/uploadAttachment',
  corpo: { contentType: 'application/pdf', file: e.arquivo, filename: e.nomeArquivo },
} }];

// Regras da troca (17/11/2026). O antigo ganha "substituidoPor" e o novo "substitui" no Dados_Json; desfazer tira
// os dois. Só documentos do mesmo cliente e da mesma pasta; nota fiscal não entra (tem o cancelamento próprio).
const e = $('Le entrada').first().json;
const http = $input.first().json || {};
const responder = (resposta) => [{ json: { proximo: 'responder', resposta } }];
if (http.error || !Array.isArray(http.records)) return responder({ ok: false, mensagem: 'Não foi possível falar com o banco agora. Tente de novo em instantes.' });
const achar = (id) => http.records.find((r) => r.id === id && r.fields && r.fields.Cliente_Ref === e.clienteId);
// Corrigir um documento (22/11/2026). Gerado pelo sistema: só título e descrição (data, valor e emissor estão escritos
// no PDF; para mudar, gerar outro e usar "Substituir"). Importado: tudo. O "antes" fica no Dados_Json (últimas 10).
if (e.acao === 'editar') {
  const r = achar(e.antigoId);
  if (!r) return responder({ ok: false, mensagem: 'Não achei este documento na pasta do cliente. Atualize a tela e tente de novo.' });
  const f = r.fields;
  let d = {};
  try { d = f.Dados_Json ? JSON.parse(f.Dados_Json) : {}; } catch (err) { d = null; }
  if (!d || typeof d !== 'object' || Array.isArray(d)) d = null;
  const gerado = f.Origem !== 'importado';
  const antes = { titulo: f.Titulo || '', descricao: f.Descricao || '', data: String(f.Data_Documento || '').slice(0, 10),
    valor: typeof f.Valor === 'number' ? f.Valor : null, emissor: f.Emissor || 'CNPJ 1' };
  const depois = { ...antes, titulo: e.titulo, descricao: e.descricao };
  if (!gerado) {
    depois.data = e.dataDocumento;
    depois.emissor = e.emissor;
    if (['nfs', 'orcamento', 'recibo'].includes(f.Tipo)) depois.valor = e.valor;
  }
  if (JSON.stringify(depois) === JSON.stringify(antes)) return responder({ ok: true, mensagem: 'Nada mudou.' });
  const fields = { Titulo: depois.titulo, Descricao: depois.descricao };
  if (!gerado) {
    Object.assign(fields, { Data_Documento: depois.data, Emissor: depois.emissor, Valor: depois.valor,
      Texto_Busca: [depois.titulo, depois.descricao, d && d.arquivoOriginal].filter(Boolean).join(' | ') });
  }
  if (d) {
    const agora = new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 16).replace('T', ' ');
    d.edicoes = [...(Array.isArray(d.edicoes) ? d.edicoes : []), { em: agora, antes }].slice(-10);
    fields.Dados_Json = JSON.stringify(d);
  }
  return [{ json: { proximo: 'gravar', corpo: { records: [{ id: r.id, fields }] } } }];
}
const antigo = achar(e.antigoId);
const novo = achar(e.novoId);
if (!antigo || !novo) return responder({ ok: false, mensagem: 'Não achei os dois documentos na pasta deste cliente. Atualize a tela e tente de novo.' });
const ler = (r) => {
  const t = r.fields.Dados_Json;
  if (!t) return {};
  try { const d = JSON.parse(t); return d && typeof d === 'object' && !Array.isArray(d) ? d : null; } catch (err) { return null; }
};
const dA = ler(antigo);
const dN = ler(novo);
if (!dA || !dN) return responder({ ok: false, mensagem: 'Os dados guardados de um dos documentos estão num formato que o app não altera. Peça pelo chat.' });
const reais = (v) => (typeof v === 'number' ? ' · R$ ' + v.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.') : '');
const data = (r) => String(r.fields.Data_Documento || '').slice(0, 10);
const resumo = (r) => (String(r.fields.Titulo || 'Documento') + reais(r.fields.Valor)).slice(0, 200);
const hoje = new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 10);

if (e.acao === 'substituir') {
  if (antigo.fields.Tipo !== novo.fields.Tipo) return responder({ ok: false, mensagem: 'Só dá para substituir por um documento da mesma pasta.' });
  if (dA.substituidoPor) return responder({ ok: false, mensagem: 'Este documento já foi substituído. Desfaça a troca antes de escolher outro.' });
  if (dN.substituidoPor) return responder({ ok: false, mensagem: 'O documento escolhido também já foi substituído. Escolha o mais recente.' });
  if (dN.substitui) return responder({ ok: false, mensagem: 'O documento escolhido já substitui outro. Escolha outro ou desfaça aquela troca.' });
  dA.substituidoPor = { id: novo.id, data: data(novo), titulo: resumo(novo), motivo: e.motivo, em: hoje };
  dN.substitui = { id: antigo.id, data: data(antigo), titulo: resumo(antigo), motivo: e.motivo, em: hoje };
} else {
  const sp = dA.substituidoPor;
  if (!sp || (sp.id && sp.id !== novo.id)) return responder({ ok: false, mensagem: 'Este documento não está marcado como substituído por esse. Atualize a tela.' });
  delete dA.substituidoPor;
  if (dN.substitui && (!dN.substitui.id || dN.substitui.id === antigo.id)) delete dN.substitui;
}
return [{ json: { proximo: 'gravar', corpo: { records: [
  { id: antigo.id, fields: { Dados_Json: JSON.stringify(dA) } },
  { id: novo.id, fields: { Dados_Json: JSON.stringify(dN) } },
] } } }];

const e = $('Le entrada').first().json;
if (e.acao === 'editar') return [{ json: { ok: true, mensagem: 'Pronto: dados do documento corrigidos.' } }];
return [{ json: { ok: true, mensagem: e.acao === 'desfazer' ? 'Troca desfeita: os dois documentos voltaram ao normal.' : 'Pronto: o documento antigo ficou marcado como substituído.' } }];

// O banco grava os dois juntos ou nenhum: se deu erro, nada mudou.
if ($('Le entrada').first().json.acao === 'editar') return [{ json: { ok: false, mensagem: 'Não consegui guardar a correção agora. Nada foi mudado; tente de novo.' } }];
return [{ json: { ok: false, mensagem: 'Não consegui gravar a troca agora. Nada foi mudado; tente de novo.' } }];
